css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.container.container-alt {
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

.container-fluid {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-right: 1.5rem;
  padding-left: 1.5rem;
}

.content-box {
  font-size: 0.875rem;
}

.content-box-sm {
  font-size: 0.875rem;
  color: #6c757d;
  border-right: 1px solid #dee2e6;
  padding-right: 1rem;
  margin-right: 1.5rem;
}

.icon-envelope-fill {
  color: #0d6efd;
  margin-right: 0.5rem;
}

.accent-text {
  color: #0d6efd;
}

.accent-text-alt {
  color: #6c757d;
  margin-right: 1rem;
  margin-left: 1rem;
}

.icon-telephone-fill {
  color: #0d6efd;
  margin-right: 0.5rem;
}

.flex-group {
  display: flex;
  align-items: center;
}

.action-link {
  color: #ffffff;
  margin-right: 0.5rem;
  margin-left: 0.5rem;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  padding: 0.25rem 1rem;
  margin-left: 1rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.navbar {
  position: sticky;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  color: #212529;
  border-bottom-left-radius: 1rem;
  border-bottom-right-radius: 1rem;
  background-color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  top: 0;
  z-index: 1020;
  padding: 0.75rem 1.5rem;
}

.navbar>.container,
.navbar>.container-fluid {
  display: flex;
  flex-wrap: inherit;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  font-size: 1.75rem;
  text-decoration: none;
  white-space: nowrap;
  color: inherit;
  font-weight: 700;
  padding-top: 0.3125rem;
  padding-bottom: 0.3125rem;
  margin-right: 1rem;
}

.nav-toggle {
  font-size: 1.25rem;
  line-height: 1;
  color: inherit;
  background-color: transparent;
  border: 1px solid rgba(128, 128, 128, 0.35);
  border-radius: 0.375rem;
  cursor: pointer;
  padding: 0.25rem 0.75rem;
}

.nav-toggle-icon {
  display: inline-block;
  width: 1.5em;
  height: 1.5em;
  vertical-align: middle;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%28128, 128, 128, 0.85%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100%;
}

.nav-collapse {
  display: none;
  flex-basis: 100%;
  flex-grow: 1;
  align-items: center;
}

.nav-collapse.show {
  display: block;
}

.custom-nav {
  display: flex;
  flex-direction: column;
  list-style: none;
  font-weight: 600;
  padding-left: 0;
  margin-top: 0;
  margin-bottom: 0;
  margin-left: auto;
}

.nav-item {
  list-style: none;
}

.nav-link {
  display: block;
  color: inherit;
  text-decoration: none;
  background: none;
  border: 0;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
  padding: 0.5rem 1rem;
}

.nav-link.nav-link-alt {
  padding-right: 0.85rem;
}

@media (min-width: 992px) {
  .navbar {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .nav-toggle {
    display: none;
  }

  .nav-collapse {
    display: flex !important;
    flex-basis: auto;
  }

  .custom-nav {
    flex-direction: row;
    align-items: center;
  }
}

/* Custom Component Styles */
.custom-nav .nav-link {
  position: relative;
  transition: color 0.3s;
}

.custom-nav .nav-link::after {
  content: '';
  position: absolute;
  width: 0;
  height: 2px;
  bottom: 0;
  left: 0;
  background-color: #0d6efd;
  transition: width 0.3s;
}

.custom-nav .nav-link:hover::after {
  width: 100%;
}


@keyframes float {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-20px);
  }
}

