// Toggle collapsible sections & mobile menu
document.querySelectorAll('[data-toggle="collapse"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const target = targetSel ? document.querySelector(targetSel) : null;
    if (!target) return;
    const parentSel = target.getAttribute("data-parent");
    if (parentSel) {
      const parent = document.querySelector(parentSel);
      if (parent) {
        parent.querySelectorAll(".show").forEach((openEl) => {
          if (openEl !== target) openEl.classList.remove("show");
        });
        parent.querySelectorAll('[data-toggle="collapse"]').forEach((otherBtn) => {
          if (otherBtn !== btn) otherBtn.classList.add("collapsed");
        });
      }
    }
    const isOpen = target.classList.toggle("show");
    btn.classList.toggle("collapsed", !isOpen);
  });
});

// Current Date & Time
function updateDateTime() {
  const now = new Date();
  const options = {
    weekday: 'short',
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  };
  document.getElementById('dateTimeDisplay').innerText = now.toLocaleDateString('en-US', options);
}
setInterval(updateDateTime, 1000);
updateDateTime();

