  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding: 1.5rem 1rem;
  margin-top: 0.5rem;
  margin-right: auto;
  margin-left: auto;
}

.hero-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  padding: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.hero-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.hero-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.hero-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.hero-row-3 {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  align-items: center;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.hero-row-3>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.hero-row-light {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  border-radius: 1rem;
  background-color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  text-align: center;
  border: 1px solid #dee2e6;
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
  margin-top: 3rem;
  margin-right: 0;
  margin-left: 0;
}

.hero-row-light>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-quarter {
  width: 50%;
  flex: 0 0 auto;
}

.col-quarter-alt {
  width: 50%;
  flex: 0 0 auto;
}

.col-quarter-3 {
  width: 100%;
  display: none;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  overflow: hidden;
  border: 0;
}

.content-box {
  background-color: #0d6efd;
  padding: 1rem;
}

.label-title {
  font-weight: 700;
  font-size: 0.875rem;
  margin-bottom: 0;
}

.label-title-alt {
  color: #ffffff;
  font-weight: 700;
  margin-bottom: 0;
}

.icon-list {
  margin-right: 0.5rem;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  border-radius: 0;
  padding-left: 0;
  margin-bottom: 0;
}

.list-item {
  position: relative;
  display: block;
  color: #212529;
  text-decoration: none;
  background-color: #ffffff;
  border: 0;
  padding: 1rem;
}

.action-link {
  text-decoration: none;
  color: #212529;
}

.action-link-alt {
  text-decoration: none;
  color: #0d6efd;
  font-weight: 700;
}

.icon-laptop {
  margin-right: 1rem;
}

.icon-watch {
  margin-right: 1rem;
}

.icon-camera {
  margin-right: 1rem;
}

.icon-headphones {
  margin-right: 1rem;
}

.icon-controller {
  margin-right: 1rem;
}

.col-wide {
  width: 100%;
  text-align: center;
}

.col-wide-alt {
  width: 100%;
}

.carousel {
  position: relative;
  border-radius: 2rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  overflow: hidden;
  border: 1px solid #dee2e6;
}

.carousel-indicators {
  position: absolute;
  right: 0;
  bottom: 0.75rem;
  left: 0;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.carousel-indicators>* {
  width: 28px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background-color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
}

.carousel-indicators>.active {
  background-color: #ffffff;
}

.action-btn {
  border-radius: 50%;
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
  background-color: #ffffff;
}

.carousel-item.active {
  display: block;
}

.carousel-item.carousel-item-alt {
  background-color: #fcfcfd;
}

.badge {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #ffffff;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #dc3545;
  padding: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.badge-primary {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #ffffff;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #0d6efd;
  padding: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.hero-title {
  font-size: clamp(2rem, 3.5vw, 3.5rem);
  line-height: 1.2;
  font-weight: 900;
  color: #212529;
  margin-bottom: 1rem;
}

.accent-text {
  color: #0d6efd;
}

.accent-text-alt {
  color: #ffc107;
}

.lead-text {
  font-size: 1.25rem;
  font-weight: 300;
  color: #6c757d;
  margin-bottom: 1.5rem;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 0.65rem 1.5rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.col-side {
  width: 100%;
  text-align: center;
  margin-top: 1.5rem;
}

.animate-float {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
}

.btn-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #212529;
  color: #ffffff;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 0.65rem 1.5rem;
}

.btn-dark:hover {
  background-color: #424649;
  border-color: #424649;
  color: #ffffff;
}

.col-sixth {
  width: 100%;
}

.col-full {
  flex: 0 0 auto;
  width: 100%;
}

.hover-overlay {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  overflow: hidden;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  color: #ffffff;
  height: 100%;
  border: 0;
}

.card-img {
  width: 100%;
  display: block;
  border-radius: calc(0.5rem - 1px);
}

.card-overlay {
  position: absolute;
  inset: 0;
  border-radius: calc(0.5rem - 1px);
  background-color: rgba(33, 37, 41, 0.25);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: 100%;
  padding: 1rem;
  margin-top: 3rem;
}

.text-desc {
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 0;
}

.item-title {
  font-weight: 700;
  font-size: 1rem;
}

.icon-truck {
  font-size: 1.75rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.muted-text {
  color: #6c757d;
  font-size: 0.75rem;
  margin-bottom: 0;
}

.icon-arrow-repeat {
  font-size: 1.75rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.icon-shield-check {
  font-size: 1.75rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.icon-headset {
  font-size: 1.75rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

@media (min-width: 768px) {
  .col-quarter {
    flex: 0 0 auto;
    width: 25%;
  }

  .col-quarter-alt {
    flex: 0 0 auto;
    width: 25%;
    border-left: 1px solid #dee2e6;
  }

  .col-wide {
    flex: 0 0 auto;
    width: 58.3333%;
    text-align: left;
  }

  .col-wide-alt {
    flex: 0 0 auto;
    width: 66.6667%;
  }

  .col-side {
    flex: 0 0 auto;
    width: 41.6667%;
    margin-top: 0;
  }

  .col-sixth {
    flex: 0 0 auto;
    width: 33.3333%;
  }
}

@media (min-width: 992px) {
  .container {
    padding-top: 3rem;
  }

  .hero-row {
    padding: 3rem;
  }

  .col-quarter-3 {
    flex: 0 0 auto;
    width: 25%;
    display: block;
  }

  .col-wide {
    padding-left: 1.5rem;
  }

  .col-wide-alt {
    flex: 0 0 auto;
    width: 58.3333%;
  }

  .col-sixth {
    flex: 0 0 auto;
    width: 16.6667%;
  }
}

/* Custom Component Styles */
.hero-title {
  font-weight: 900;
}

.muted-text {
  font-size: 0.75rem;
}

.sidebar-nav .list-item {
  transition: 0.2s;
}

.sidebar-nav .list-item:hover {
  background-color: #f8f9fa;
  padding-left: 1.5rem !important;
}

#heroEcommerceSlider {
  min-height: 400px;
}

.carousel-indicators [data-slide-to] {
  width: 10px;
  height: 10px;
  background-color: #0d6efd;
}

.animate-float {
  animation: floatImg 4s ease-in-out infinite;
}

@keyframes floatImg {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-15px);
  }
}

.hover-overlay:hover img {
  transform: scale(1.1);
  transition: 0.5s ease;
}

.card-img {
  height: 190px;
  object-fit: cover;
}

@media (min-width: 768px) {
  .col-quarter-alt {
    border-left: 1px solid #dee2e6 !important;
  }
}

