// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.hero-section {
  color: #ffffff;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.container {
  width: 100%;
  max-width: 1200px;
  text-align: center;
  padding: 3rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.hero-title {
  font-size: clamp(2.25rem, 4vw, 4rem);
  line-height: 1.2;
  font-weight: 700;
}

.lead-text {
  font-size: 1.25rem;
  font-weight: 300;
  opacity: 0.75;
  margin-top: 1rem;
}

.btn-light {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #f8f9fa;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #f8f9fa;
  color: #000000;
  padding: 0.65rem 1.5rem;
  margin-top: 1rem;
}

.btn-light:hover {
  background-color: #d3d4d5;
  border-color: #d3d4d5;
  color: #000000;
}

.icon-arrow-right {
  margin-left: 0.25rem;
}

/* Inline SVG Icons */

.icon-arrow-right::before {
  content: "";
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: -0.125em;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
}

