*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.section-block {
  overflow: hidden;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.carousel {
  position: relative;
}

.carousel-indicators {
  position: absolute;
  right: 0;
  bottom: 0.75rem;
  left: 0;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.carousel-indicators>* {
  width: 28px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background-color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
}

.carousel-indicators>.active {
  background-color: #ffffff;
}

.action-btn {
  background-color: #0d6efd;
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: 2rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  background-color: #ffffff;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
  padding: 1.5rem;
}

.carousel-item.active {
  display: block;
}

.animation-container {
  display: flex;
  flex-wrap: wrap;
  row-gap: 3rem;
  align-items: center;
  margin-right: -1.5rem;
  margin-left: -1.5rem;
}

.animation-container>* {
  width: 100%;
  max-width: 100%;
  padding-right: 1.5rem;
  padding-left: 1.5rem;
}

.col-half {
  width: 100%;
  order: 2;
  text-align: center;
}

.col-half-center {
  width: 100%;
  order: 1;
  text-align: center;
}

.col-half-3 {
  width: 100%;
  order: 1;
  text-align: center;
  position: relative;
}

.badge {
  display: inline-block;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1;
  color: #212529;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #f8f9fa;
  border: 1px solid #dee2e6;
  padding: 1rem;
}

.badge-pill {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #0d6efd;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #cfe2ff;
  padding: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.hero-title {
  font-size: clamp(2.25rem, 4vw, 4rem);
  line-height: 1.2;
  font-weight: 900;
  margin-bottom: 0.5rem;
}

.accent-text {
  color: #0d6efd;
}

.accent-text-alt {
  color: #198754;
}

.accent-text-3 {
  color: #0dcaf0;
}

.section-title {
  font-size: clamp(2rem, 3.5vw, 3.5rem);
  line-height: 1.2;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.section-title-alt {
  font-size: 1.75rem;
  font-weight: 300;
  line-height: 1.2;
  color: #6c757d;
  margin-bottom: 1.5rem;
}

.lead-text {
  font-size: 1.25rem;
  font-weight: 300;
  color: #6c757d;
  margin-bottom: 1.5rem;
}

.lead-text-alt {
  font-size: 1.25rem;
  font-weight: 300;
  color: #6c757d;
  margin-bottom: 3rem;
}

.flex-center {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.flex-center-center {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: center;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 1rem 1.5rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.icon-send-fill {
  margin-right: 0.5rem;
}

.btn-outline-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: transparent;
  color: #212529;
  padding: 1rem 1.5rem;
}

.btn-outline-dark:hover {
  background-color: #212529;
  color: #ffffff;
}

.icon-download {
  margin-right: 0.5rem;
}

.profile-blob-bg {
  margin-right: auto;
  margin-left: auto;
}

.profile-img {
  max-width: 100%;
  height: auto;
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  border: 5px solid #ffffff;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 3rem;
  align-items: center;
  margin-right: -1.5rem;
  margin-left: -1.5rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 1.5rem;
  padding-left: 1.5rem;
}

.grid-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1rem;
  margin-right: -0.5rem;
  margin-bottom: 3rem;
  margin-left: -0.5rem;
}

.grid-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.5rem;
  padding-left: 0.5rem;
}

.col-third {
  flex: 0 0 auto;
  width: 33.3333%;
  text-align: center;
}

.icon-patch-check-fill {
  color: #198754;
  font-size: 2.5rem;
}

.text-desc {
  font-size: 0.875rem;
  font-weight: 700;
  margin-top: 0.5rem;
}

.icon-speedometer2 {
  color: #0dcaf0;
  font-size: 2.5rem;
}

.icon-shield-lock-fill {
  color: #ffc107;
  font-size: 2.5rem;
}

.btn-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #212529;
  color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  padding: 0.65rem 3rem;
}

.btn-dark:hover {
  background-color: #424649;
  border-color: #424649;
  color: #ffffff;
}

.surface-box {
  border-radius: 50%;
  background-color: #f8f9fa;
  display: inline-block;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.06);
  padding: 3rem;
}

.icon-laptop {
  color: #0d6efd;
  font-size: clamp(2.75rem, 5vw, 5rem);
  font-weight: 300;
  line-height: 1.2;
}

.content-box {
  margin-top: 3rem;
}

.btn-info {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0dcaf0;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0dcaf0;
  color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  padding: 0.65rem 3rem;
}

.btn-info:hover {
  background-color: #31d2f2;
  border-color: #31d2f2;
  color: #000000;
}

.rotate-img {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.carousel-prev {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0 0 0 1rem;
}

.carousel-prev:hover {
  opacity: 1;
}

.carousel-prev-icon {
  display: inline-block;
  width: 2rem;
  height: 2rem;
  background-repeat: no-repeat;
  background-position: 50%;
  background-size: 100% 100%;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M11.354 1.646a.5.5 0 0 1 0 .708L5.707 8l5.647 5.646a.5.5 0 0 1-.708.708l-6-6a.5.5 0 0 1 0-.708l6-6a.5.5 0 0 1 .708 0z'/%3e%3c/svg%3e");
  border-radius: 50%;
  background-color: #212529;
  padding: 1rem;
}

.carousel-next {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0 1rem 0 0;
}

.carousel-next:hover {
  opacity: 1;
}

.carousel-next-icon {
  display: inline-block;
  width: 2rem;
  height: 2rem;
  background-repeat: no-repeat;
  background-position: 50%;
  background-size: 100% 100%;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M4.646 1.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1 0 .708l-6 6a.5.5 0 0 1-.708-.708L10.293 8 4.646 2.354a.5.5 0 0 1 0-.708z'/%3e%3c/svg%3e");
  border-radius: 50%;
  background-color: #212529;
  padding: 1rem;
}

@media (min-width: 768px) {
  .carousel-item {
    padding: 3rem;
  }

  .flex-center-center {
    flex-direction: row;
  }
}

@media (min-width: 992px) {
  .col-half {
    flex: 0 0 auto;
    width: 50%;
    order: 1;
    text-align: left;
  }

  .col-half-center {
    flex: 0 0 auto;
    width: 50%;
    order: 2;
  }

  .col-half-3 {
    flex: 0 0 auto;
    width: 50%;
    order: 2;
  }

  .flex-center {
    justify-content: flex-start;
  }

  .flex-center-center {
    justify-content: flex-start;
  }
}

/* Custom Component Styles */
.profile-img {
  max-width: 380px;
  z-index: 2;
}

.profile-blob-bg {
  background: linear-gradient(45deg, #0d6efd22, #0dcaf022);
  border-radius: 62% 38% 52% 48% / 51% 43% 57% 49%;
  padding: 20px;
  animation: blobAnimate 8s ease-in-out infinite;
}

.profile-img {
  animation: float 6s ease-in-out infinite;
}

.icon-laptop {
  animation: pulse 3s infinite;
}

.rotate-img {
  transform: rotate(3deg);
  transition: transform 0.5s ease;
}

.rotate-img:hover {
  transform: rotate(0deg);
}

@keyframes blobAnimate {
  0% {
    border-radius: 62% 38% 52% 48% / 51% 43% 57% 49%;
  }

  50% {
    border-radius: 40% 60% 35% 65% / 45% 55% 45% 55%;
  }

  100% {
    border-radius: 62% 38% 52% 48% / 51% 43% 57% 49%;
  }
}

@keyframes float {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-20px);
  }
}

@keyframes pulse {
  0% {
    transform: scale(1);
    opacity: 1;
  }

  50% {
    transform: scale(1.1);
    opacity: 0.8;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.hero-title {
  font-weight: 900;
}

.carousel-item {
  transition: transform 0.8s ease-in-out, opacity 0.8s ease-in-out;
}

@media (max-width: 768px) {
  .profile-img {
    max-width: 250px;
  }

  .hero-title {
    font-size: 2.5rem;
  }
}

