js:
// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.section-block {
  background-color: #212529;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding: 1.5rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-title {
  font-weight: 700;
  color: #ffffff;
}

.muted-text {
  color: rgba(255, 255, 255, 0.5);
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-narrow {
  width: 100%;
}

.carousel {
  position: relative;
  border-radius: 1rem;
  overflow: hidden;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
}

.carousel-item.active {
  display: block;
}

.feature-img {
  display: block;
  width: 100%;
}

.carousel-caption {
  position: absolute;
  right: 15%;
  bottom: 1.25rem;
  left: 15%;
  color: #ffffff;
  text-align: center;
  display: none;
  background-color: rgba(33, 37, 41, 0.75);
  padding-top: 1.25rem;
  padding-bottom: 1.25rem;
}

.carousel-prev {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12%;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0;
}

.carousel-prev:hover {
  opacity: 1;
}

.carousel-prev-icon {
  display: inline-block;
  width: 2rem;
  height: 2rem;
  background-repeat: no-repeat;
  background-position: 50%;
  background-size: 100% 100%;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M11.354 1.646a.5.5 0 0 1 0 .708L5.707 8l5.647 5.646a.5.5 0 0 1-.708.708l-6-6a.5.5 0 0 1 0-.708l6-6a.5.5 0 0 1 .708 0z'/%3e%3c/svg%3e");
}

.carousel-next {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12%;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0;
}

.carousel-next:hover {
  opacity: 1;
}

.carousel-next-icon {
  display: inline-block;
  width: 2rem;
  height: 2rem;
  background-repeat: no-repeat;
  background-position: 50%;
  background-size: 100% 100%;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M4.646 1.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1 0 .708l-6 6a.5.5 0 0 1-.708-.708L10.293 8 4.646 2.354a.5.5 0 0 1 0-.708z'/%3e%3c/svg%3e");
}

@media (min-width: 768px) {
  .carousel-caption {
    display: block;
  }
}

@media (min-width: 992px) {
  .col-narrow {
    flex: 0 0 auto;
    width: 83.3333%;
  }
}

