document.querySelectorAll('[data-count]').forEach(el => {
  const t = +el.dataset.count;
  let n = 0;
  const s = Math.max(1, Math.floor(t / 60));
  const i = setInterval(() => {
    n += s;
    if (n >= t) {
      n = t;
      clearInterval(i)
    }
    el.textContent = n.toLocaleString()
  }, 20)
});

