document.addEventListener("DOMContentLoaded", function() {
  var end = Date.now() + 3 * 864e5;
  var x = setInterval(function() {
    var d = end - Date.now();
    if (d < 0) {
      clearInterval(x);
      return
    }
    var p = function(n) {
      return n < 10 ? "0" + n : n
    };
    days.innerHTML = p(Math.floor(d / 864e5));
    hours.innerHTML = p(Math.floor(d % 864e5 / 36e5));
    minutes.innerHTML = p(Math.floor(d % 36e5 / 6e4));
    seconds.innerHTML = p(Math.floor(d % 6e4 / 1e3))
  }, 1e3)
});

