js:
const s = document.getElementById('usage-slider'),
  v = document.getElementById('usage-val'),
  p = document.getElementById('usage-price');
if (s) {
  s.addEventListener('input', () => {
    const n = +s.value;
    v.textContent = n >= 1000 ? '1M' : n + 'k';
    p.textContent = Math.max(10, Math.round(n * 0.1));
  })
}

