// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

// Modal, Toast & Alert triggers
document.querySelectorAll('[data-toggle="modal"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const modal = targetSel ? document.querySelector(targetSel) : null;
    if (modal) {
      modal.classList.add("show");
      modal.removeAttribute("aria-hidden");
      modal.setAttribute("aria-modal", "true");
    }
  });
});

document.querySelectorAll("[data-dismiss]").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const kind = btn.getAttribute("data-dismiss");
    const target = btn.closest("." + kind + ", .alert-box, .modal, .toast");
    if (target) {
      target.classList.remove("show");
      if (target.classList.contains("modal") || kind === "modal") {
        target.setAttribute("aria-hidden", "true");
        target.removeAttribute("aria-modal");
      }
      if (kind === "alert") target.style.display = "none";
    }
  });
});

// 3. Confirmation popup window when submit (Requirement 3)
document.addEventListener('DOMContentLoaded', function() {
  const form = document.getElementById('adminLoginForm');
  const confirmModal = ({
    el: document.getElementById('loginConfirmModal'),
    show() {
      if (this.el) {
        this.el.classList.add("show");
        this.el.removeAttribute("aria-hidden");
        this.el.setAttribute("aria-modal", "true");
      }
    },
    hide() {
      if (this.el) {
        this.el.classList.remove("show");
        this.el.setAttribute("aria-hidden", "true");
        this.el.removeAttribute("aria-modal");
      }
    }
  });

  if (form) {
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      // Perform validation check if needed
      confirmModal.show();
      // form.reset(); // Optional reset
    });
  }
});

