*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding: 3rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-side {
  width: 100%;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 0.5rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  border: 0;
}

.card-body {
  flex: 1 1 auto;
  padding: 1.5rem;
}

.sub-title {
  font-weight: 700;
  text-align: center;
  margin-bottom: 1.5rem;
}

.content-box {
  margin-bottom: 1rem;
}

.form-label {
  display: inline-block;
  margin-bottom: 0.5rem;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
  border-radius: 0.375rem;
  border: 1px solid #dee2e6;
  padding: 0.5rem 0.75rem;
}

.form-input:focus {
  border-color: #86b7fe;
  outline: 0;
  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.flex-between {
  display: flex;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.form-check {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 1.5rem;
  margin-bottom: 0.25rem;
}

.check-input {
  width: 1.1em;
  height: 1.1em;
  accent-color: #0d6efd;
  cursor: pointer;
  margin: 0;
}

.check-label {
  cursor: pointer;
}

.action-link {
  font-size: 0.875rem;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 0.375rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  width: 100%;
  padding: 0.5rem 1rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

@media (min-width: 768px) {
  .col-side {
    flex: 0 0 auto;
    width: 41.6667%;
  }
}

