// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

// 3. Confirmation popup window when submit the login form
document.getElementById('loginForm').addEventListener('submit', function(e) {
  e.preventDefault();

  let loginType = document.querySelector('input[name="loginType"]:checked').id === "studentLogin" ? "Student" : "Teacher";

  const confirmLogin = confirm("Are you sure you want to log in as a " + loginType + "?");

  if (confirmLogin) {
    alert("Login Successful! Redirecting to " + loginType + " Dashboard...");
    // Redirect logic would go here
    window.location.href = "index.html";
  }
});

css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 3rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  width: 100%;
  border: 0;
}

.card-body {
  flex: 1 1 auto;
  padding: 1.5rem;
}

.section-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.icon-circle {
  border-radius: 50%;
  background-color: #cfe2ff;
  color: #0d6efd;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
}

.icon-shield-lock-fill {
  font-size: 2rem;
}

.sub-title {
  font-weight: 700;
}

.muted-text {
  color: #6c757d;
  font-size: 0.875rem;
}

.input-floating {
  position: relative;
  margin-bottom: 1rem;
}

.input-floating>input,
.input-floating>textarea,
.input-floating>select {
  padding-top: 1.4rem;
  padding-bottom: 0.4rem;
}

.input-floating>label {
  position: absolute;
  top: 0.25rem;
  left: 0.75rem;
  font-size: 0.75rem;
  color: #6c757d;
  pointer-events: none;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
  border-radius: 0.375rem;
  border: 1px solid #dee2e6;
  padding: 0.5rem 0.75rem;
}

.form-input:focus {
  border-color: #86b7fe;
  outline: 0;
  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.icon-person {
  color: #6c757d;
  margin-right: 0.5rem;
}

.icon-lock {
  color: #6c757d;
  margin-right: 0.5rem;
}

.flex-between {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
}

.form-check {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 1.5rem;
  margin-bottom: 0.25rem;
}

.check-input {
  width: 1.1em;
  height: 1.1em;
  accent-color: #0d6efd;
  cursor: pointer;
  margin: 0;
}

.check-label {
  cursor: pointer;
  color: #6c757d;
}

.action-link {
  color: #0d6efd;
  text-decoration: none;
  font-weight: 500;
}

.action-link-alt {
  color: #0d6efd;
  font-weight: 700;
  text-decoration: none;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 0.5rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  width: 100%;
  padding: 1rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.icon-arrow-right {
  margin-left: 0.25rem;
}

.content-box {
  text-align: center;
  font-size: 0.875rem;
  color: #6c757d;
  border-top: 1px solid #dee2e6;
  padding-top: 1rem;
  margin-top: 1.5rem;
}

.toast-wrap {
  z-index: 1090;
  position: fixed;
  bottom: 0;
  right: 0;
  padding: 1rem;
}

.toast {
  width: 350px;
  max-width: 100%;
  font-size: 0.875rem;
  background-color: #198754;
  border: 0;
  border-radius: 0.5rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  display: none;
  align-items: center;
  color: #ffffff;
}

.toast.show {
  display: block;
}

.flex-group {
  display: flex;
}

.toast-body {
  font-weight: 500;
  padding: 0.75rem;
}

.icon-check-circle-fill {
  margin-right: 0.5rem;
}

.btn-close {
  width: 1em;
  height: 1em;
  background: transparent url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M.293.293a1 1 0 0 1 1.414 0L8 6.586 14.293.293a1 1 0 1 1 1.414 1.414L9.414 8l6.293 6.293a1 1 0 0 1-1.414 1.414L8 9.414l-6.293 6.293a1 1 0 0 1-1.414-1.414L6.586 8 .293 1.707a1 1 0 0 1 0-1.414z'/%3e%3c/svg%3e") center/1em auto no-repeat;
  border: 0;
  border-radius: 0.375rem;
  opacity: 0.5;
  cursor: pointer;
  padding: 0.25em;
  margin: auto 0.5rem auto auto;
}

@media (min-width: 768px) {
  .card-body {
    padding: 3rem;
  }
}

