// Modal, Toast & Alert triggers
document.querySelectorAll('[data-toggle="modal"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const modal = targetSel ? document.querySelector(targetSel) : null;
    if (modal) {
      modal.classList.add("show");
      modal.removeAttribute("aria-hidden");
      modal.setAttribute("aria-modal", "true");
    }
  });
});

document.querySelectorAll("[data-dismiss]").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const kind = btn.getAttribute("data-dismiss");
    const target = btn.closest("." + kind + ", .alert-box, .modal, .toast");
    if (target) {
      target.classList.remove("show");
      if (target.classList.contains("modal") || kind === "modal") {
        target.setAttribute("aria-hidden", "true");
        target.removeAttribute("aria-modal");
      }
      if (kind === "alert") target.style.display = "none";
    }
  });
});

document.addEventListener("DOMContentLoaded", function() {
  var f = document.getElementById("customLoginForm");
  if (f) {
    f.addEventListener("submit", function(e) {
      e.preventDefault();
      var t = ({
        el: document.getElementById("loginSuccessToast"),
        show() {
          if (this.el) {
            this.el.classList.add("show");
            this.el.removeAttribute("aria-hidden");
            this.el.setAttribute("aria-modal", "true");
          }
        },
        hide() {
          if (this.el) {
            this.el.classList.remove("show");
            this.el.setAttribute("aria-hidden", "true");
            this.el.removeAttribute("aria-modal");
          }
        }
      });
      t.show()
    })
  }
});

