  margin-left: 0;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0;
  padding-left: 0;
}

.grid-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1rem;
  margin-right: -0.5rem;
  margin-left: -0.5rem;
}

.grid-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.5rem;
