}

.col-wide {
  width: 100%;
}

.content-box {
  padding: 1.5rem;
}

.heading-title {
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.col-half {
  flex: 0 0 auto;
  width: 50%;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
  border-radius: 0.375rem;
  border: 1px solid #dee2e6;
  padding: 0.5rem 0.75rem;
}

.form-input:focus {
  border-color: #86b7fe;
  outline: 0;
  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.col-full {
  flex: 0 0 auto;
  width: 100%;
}

.btn-primary {
  display: inline-flex;
