  font-size: 1rem;
  font-weight: 600;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 0.375rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  width: 100%;
