.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-third {
  width: 100%;
}

.item-title {
  font-weight: 700;
}

.muted-text {
  color: rgba(255, 255, 255, 0.5);
}

.col-sixth {
  width: 100%;
}

.label-title {
  font-weight: 700;
}

.clean-list {
  list-style: none;
  font-size: 0.875rem;
  padding-left: 0;
  margin-bottom: 0;
}

.action-link {
  color: rgba(255, 255, 255, 0.5);
  text-decoration: none;
}

.form-box {
  display: flex;
  gap: 0.5rem;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
