// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

