select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.section-block {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-light {
  background-color: #f8f9fa;
  border-bottom: 1px solid #dee2e6;
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 0.5rem;
  padding: 0;
  margin-bottom: 0;
}

.breadcrumb-item+.breadcrumb-item::before {
  content: "/";
  color: #6c757d;
  padding-right: 0.5rem;
}

.action-link {
  text-decoration: none;
}

.action-link-alt {
  font-weight: 700;
  color: #0d6efd;
}

.action-link-sm {
  font-size: 0.875rem;
  text-decoration: none;
  color: #6c757d;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.grid-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 3rem;
  align-items: center;
  margin-right: -1.5rem;
  margin-left: -1.5rem;
}

.grid-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 1.5rem;
  padding-left: 1.5rem;
}

.col-side {
  width: 100%;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  overflow: hidden;
  border: 0;
}

.card-header {
  background-color: #0d6efd;
  border-bottom: 1px solid rgba(0, 0, 0, 0.125);
  padding: 1rem;
}

.heading-title {
  font-weight: 700;
}

.heading-title-center {
  color: #ffffff;
  text-align: center;
  font-weight: 700;
  margin-bottom: 0;
}

.card-body {
  flex: 1 1 auto;
  padding: 1.5rem;
}

.btn-group {
  display: inline-flex;
  vertical-align: middle;
  width: 100%;
  margin-bottom: 1.5rem;
}

.radio-toggle {
  position: absolute;
  clip: rect(0, 0, 0, 0);
  pointer-events: none;
}

.radio-toggle:checked+label {
  background-color: #0d6efd;
  color: #ffffff;
  border-color: #0d6efd;
}

.btn-outline-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 0.375rem;
  transition: all 0.2s ease;
  background-color: transparent;
  color: #0d6efd;
  padding: 0.5rem 1rem;
}

.btn-outline-primary:hover {
  background-color: #0d6efd;
  color: #ffffff;
}

.icon-person-badge {
  margin-right: 0.5rem;
}

.icon-person-workspace {
  margin-right: 0.5rem;
}

.content-box {
  margin-bottom: 1rem;
}

.content-box-alt {
  margin-bottom: 1.5rem;
}

.content-box-4 {
  margin-top: 1.5rem;
}

.content-box-5 {
  margin-top: 3rem;
}

.content-box-end {
  text-align: right;
  margin-top: 0.5rem;
}

.content-box-center {
  text-align: center;
  margin-top: 1.5rem;
}

.form-label {
  display: inline-block;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.input-group {
  position: relative;
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch;
  width: 100%;
}

.input-group>input,
.input-group>select,
.input-group>textarea {
  position: relative;
  flex: 1 1 auto;
  width: 1%;
  min-width: 0;
}

.input-addon {
  display: flex;
  align-items: center;
  font-size: 1rem;
  color: #212529;
  background-color: #f8f9fa;
  border-radius: 0.375rem;
  border: 1px solid #dee2e6;
  border-right: 0;
  padding: 0.5rem 0.75rem;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  color: #212529;
  background-color: #f8f9fa;
  border-radius: 0.375rem;
  border: 1px solid #dee2e6;
  border-left: 0;
  padding: 0.5rem 0.75rem;
}

.form-input:focus {
  border-color: #86b7fe;
  outline: 0;
  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  width: 100%;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 0.5rem 1rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.icon-box-arrow-in-right {
  margin-left: 0.5rem;
}

.muted-text {
  color: #6c757d;
}

.muted-text-sm {
  font-size: 0.875rem;
  color: #6c757d;
  margin-bottom: 0;
}

.col-wide {
  width: 100%;
}

.section-title {
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.accent-text {
  color: #0d6efd;
}

.carousel {
  position: relative;
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
}

.carousel-item.active {
  display: block;
}

.surface-box {
  border-radius: 1rem;
  background-color: #f8f9fa;
  border-left: 5px solid #0d6efd;
  padding: 3rem;
}

.surface-box-light {
  border-radius: 1rem;
  background-color: #f8f9fa;
  border-left: 5px solid #ffc107;
  padding: 3rem;
}

.badge {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #ffffff;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 0.375rem;
  background-color: #0d6efd;
  padding: 0.35em 0.65em;
  margin-bottom: 1rem;
}

.badge-alt {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #212529;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 0.375rem;
  background-color: #ffc107;
  padding: 0.35em 0.65em;
  margin-bottom: 1rem;
}

.flex-group {
  display: flex;
  align-items: center;
}

.flex-group-alt {
  display: flex;
  align-items: center;
  margin-top: 1.5rem;
}

.icon-clock {
  color: #0d6efd;
  margin-right: 0.5rem;
}

.icon-clock.icon-clock-alt {
  color: #ffc107;
}

.small-note {
  font-weight: 700;
}

.small-note-alt {
  color: #6c757d;
}

.btn-white {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #dee2e6;
  border-radius: 50%;
  transition: all 0.2s ease;
  background-color: #ffffff;
  color: #212529;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  padding: 0.25rem 0.65rem;
}

.btn-white:hover {
  background-color: #f8f9fa;
  border-color: #f8f9fa;
  color: #212529;
}

.btn-white-sm {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #dee2e6;
  border-radius: 50%;
  transition: all 0.2s ease;
  background-color: #ffffff;
  color: #212529;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  padding: 0.25rem 0.65rem;
  margin-right: 0.5rem;
}

.btn-white-sm:hover {
  background-color: #f8f9fa;
  border-color: #f8f9fa;
  color: #212529;
}

.col-half {
  width: 100%;
  text-align: center;
}

.icon-shield-lock {
  font-size: 2.5rem;
  color: #198754;
  margin-right: 1rem;
}

.label-title {
  font-weight: 700;
  margin-bottom: 0;
}

.icon-headset {
  font-size: 2.5rem;
  color: #0dcaf0;
  margin-right: 1rem;
}

@media (min-width: 576px) {
  .col-half {
    flex: 0 0 auto;
    width: 50%;
    text-align: left;
  }
}

@media (min-width: 768px) {
  .card-body {
    padding: 3rem;
  }
}

@media (min-width: 992px) {
  .col-side {
    flex: 0 0 auto;
    width: 41.6667%;
  }

  .content-box-3 {
    padding-right: 1.5rem;
    padding-left: 1.5rem;
  }

  .col-wide {
    flex: 0 0 auto;
    width: 58.3333%;
  }
}

