@media (min-width: 768px) {
  .container.container-center {
    text-align: left;
    display: flex;
  }

  .container.container-5 {
    flex-direction: row;
  }

  .flex-group-3 {
    margin-top: 0;
  }

  .col-half {
    flex: 0 0 auto;
    width: 50%;
  }

  .col-quarter {
    flex: 0 0 auto;
    width: 25%;
  }

  .carousel-caption {
    display: block;
  }
}

@media (min-width: 992px) {
  .navbar {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .nav-toggle {
    display: none;
  }

  .nav-collapse {
