    width: 83.3333%;
  }

  .col-third {
    flex: 0 0 auto;
    width: 33.3333%;
  }

  .col-sixth {
    flex: 0 0 auto;
    width: 16.6667%;
  }

  .col-sixth-alt {
    flex: 0 0 auto;
    width: 16.6667%;
    margin-left: 8.3333%;
  }
}

