  color: #000000;
}

.footer-section {
  background-color: #212529;
  color: #ffffff;
  text-align: center;
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

@media (min-width: 768px) {
  .col-third {
    flex: 0 0 auto;
    width: 33.3333%;
  }
}

@media (min-width: 992px) {
  .navbar {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .nav-toggle {
    display: none;
  }

  .nav-collapse {
    display: flex !important;
    flex-basis: auto;
  }

  .nav-menu {
    flex-direction: row;
    align-items: center;
  }

  .nav-item.nav-item-alt {
    margin-left: 1rem;
  }
}

