js:
// Toggle collapsible sections & mobile menu
document.querySelectorAll('[data-toggle="collapse"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const target = targetSel ? document.querySelector(targetSel) : null;
    if (!target) return;
    const parentSel = target.getAttribute("data-parent");
    if (parentSel) {
      const parent = document.querySelector(parentSel);
      if (parent) {
        parent.querySelectorAll(".show").forEach((openEl) => {
          if (openEl !== target) openEl.classList.remove("show");
        });
        parent.querySelectorAll('[data-toggle="collapse"]').forEach((otherBtn) => {
          if (otherBtn !== btn) otherBtn.classList.add("collapsed");
        });
      }
    }
    const isOpen = target.classList.toggle("show");
    btn.classList.toggle("collapsed", !isOpen);
  });
});

css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.navbar {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  color: #ffffff;
  background-color: #212529;
  padding: 0.75rem 1rem;
}

.navbar>.container,
.navbar>.container-fluid {
  display: flex;
  flex-wrap: inherit;
  align-items: center;
  justify-content: space-between;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.container.container-alt {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.container.container-center {
  text-align: center;
  padding-top: 1rem;
  padding-bottom: 1rem;
}

.nav-brand {
  font-size: 1.25rem;
  text-decoration: none;
  white-space: nowrap;
  color: inherit;
  font-weight: 700;
  padding-top: 0.3125rem;
  padding-bottom: 0.3125rem;
  margin-right: 1rem;
}

.accent-text {
  color: #ffc107;
}

.nav-menu {
  display: flex;
  flex-direction: row;
  list-style: none;
  gap: 1rem;
  padding-left: 0;
  margin-top: 0;
  margin-bottom: 0;
  margin-left: auto;
}

.nav-item {
  list-style: none;
}

.nav-link {
  display: block;
  color: inherit;
  text-decoration: none;
  background: none;
  border: 0;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
  padding: 0.5rem 0.85rem;
}

.section-block {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-alt {
  background-color: #ffc107;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-dark {
  background-color: #212529;
  color: #ffffff;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.hero-title {
  font-size: clamp(2.5rem, 4.5vw, 4.5rem);
  line-height: 1.2;
  font-weight: 700;
}

.content-box {
  color: #ffc107;
}

.lead-text {
  font-size: 1.25rem;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
  margin-top: 1rem;
}

.btn-warning {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #ffc107;
  border-radius: 0.375rem;
  transition: all 0.2s ease;
  background-color: #ffc107;
  color: #000000;
  padding: 0.65rem 1.25rem;
  margin-top: 1rem;
}

.btn-warning:hover {
  background-color: #ffca2c;
  border-color: #ffca2c;
  color: #000000;
}

.sub-title {
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-half {
  width: 100%;
}

.action-link {
  display: block;
  text-decoration: none;
  color: #212529;
}

.feature-img {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
}

.item-title {
  font-weight: 700;
  margin-top: 1rem;
}

.small-note {
  color: #6c757d;
}

.section-title {
  font-weight: 700;
}

.btn-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 0.375rem;
  transition: all 0.2s ease;
  background-color: #212529;
  color: #ffffff;
  padding: 0.65rem 1.25rem;
  margin-top: 0.5rem;
}

.btn-dark:hover {
  background-color: #424649;
  border-color: #424649;
  color: #ffffff;
}

.footer-section {
  background-color: #000000;
  color: #ffffff;
  text-align: center;
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

@media (min-width: 768px) {
  .col-half {
    flex: 0 0 auto;
    width: 50%;
  }
}

@media (min-width: 992px) {
  .navbar {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .nav-menu {
    flex-direction: row;
    align-items: center;
  }
