*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding: 1.5rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.navbar {
  margin-bottom: 3rem;
}

.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 0.5rem;
  border-radius: 1rem;
  background-color: #f8f9fa;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  border: 0;
  padding: 1rem;
  margin-bottom: 1rem;
}

.breadcrumb-item+.breadcrumb-item::before {
  content: "/";
  color: #6c757d;
  padding-right: 0.5rem;
}

.breadcrumb-item.breadcrumb-item-alt {
  font-weight: 600;
}

.action-link {
  text-decoration: none;
  font-weight: 700;
  color: #0d6efd;
}

.section-block {
  margin-bottom: 3rem;
}

.section-block-alt {
  padding-bottom: 3rem;
}

.section-block-3 {
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
  margin-bottom: 3rem;
}

.section-block-4 {
  padding-top: 1.5rem;
  margin-bottom: 3rem;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.eyebrow-title {
  color: #0d6efd;
  font-weight: 700;
  text-transform: uppercase;
}

.section-title {
  font-weight: 700;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  justify-content: center;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.grid-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.75rem;
  padding-left: 0.75rem;
}

.col-half {
