  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  height: 100%;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  border: 0;
  padding: 1rem;
}

.icon-cpu {
  font-size: 2.5rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.label-title {
  font-weight: 700;
  margin-bottom: 0;
}

.icon-tools {
  font-size: 2.5rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.icon-lightning-charge {
  font-size: 2.5rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.icon-computer {
  font-size: 2.5rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.icon-buildings {
  font-size: 2.5rem;
  color: #0d6efd;
  margin-bottom: 0.5rem;
}

.sub-title {
