}

.table-cell {
  padding-left: 1.5rem;
}

.table-cell-end {
  text-align: right;
  padding-right: 1.5rem;
}

.carousel {
  position: relative;
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
}

.carousel-item.active {
  display: block;
}

.featured-course {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 1rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  overflow: hidden;
  border: 0;
}

.card-img-top {
  width: 100%;
