  border-top-left-radius: calc(0.5rem - 1px);
  border-top-right-radius: calc(0.5rem - 1px);
}

.card-body {
  flex: 1 1 auto;
  padding: 1.5rem;
}

.badge {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #212529;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 0.375rem;
  background-color: #ffc107;
  padding: 0.35em 0.65em;
  margin-bottom: 0.5rem;
}

.badge-alt {
  display: inline-block;
  font-size: 0.75em;
  font-weight: 700;
  line-height: 1;
  color: #ffffff;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 0.375rem;
  background-color: #198754;
  padding: 0.35em 0.65em;
  margin-bottom: 0.5rem;
}

.item-title {
  font-weight: 700;
}

.muted-text {
