  background-color: transparent;
  color: #0d6efd;
  padding: 0.25rem 0.65rem;
}

.btn-outline-primary:hover {
  background-color: #0d6efd;
  color: #ffffff;
}

.carousel-prev {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12%;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0;
}

.carousel-prev:hover {
  opacity: 1;
}

.circle-tag {
  border-radius: 50%;
  background-color: #212529;
  padding: 0.5rem;
}

.carousel-next {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12%;
  color: #ffffff;
  background: none;
  border: 0;
  opacity: 0.8;
  cursor: pointer;
  padding: 0;
}

.carousel-next:hover {
  opacity: 1;
}

@media (min-width: 768px) {
  .col-half {
    flex: 0 0 auto;
