css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.container.container-center {
  text-align: center;
  justify-content: space-between;
}

.container.container-3 {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
}

.flex-group {
  display: flex;
  margin-bottom: 1rem;
}

.flex-group-sm {
  display: flex;
  gap: 1rem;
  font-size: 0.875rem;
}

.flex-group-3 {
  display: flex;
  gap: 1rem;
  font-size: 1.25rem;
  margin-top: 1.5rem;
}

.flex-group-4 {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 0.5rem;
}

.icon-envelope-fill {
  color: #0d6efd;
  margin-right: 0.25rem;
}

.icon-envelope-fill.icon-envelope-fill-alt {
  margin-right: 0.5rem;
}

.icon-telephone-fill {
  color: #0d6efd;
  margin-right: 0.25rem;
}

.icon-telephone-fill.icon-telephone-fill-alt {
  margin-right: 0.5rem;
}

.text-span {
  font-size: 0.875rem;
  border-right: 1px solid #dee2e6;
  padding-right: 1rem;
  margin-right: 0.5rem;
}

.action-link {
  color: #ffffff;
}

.action-link-alt {
  text-decoration: none;
}

.action-link-sm {
  color: #ffffff;
  text-decoration: none;
  font-size: 0.875rem;
}

.icon-person-circle {
  margin-right: 0.25rem;
}

.navbar {
  position: sticky;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  color: #212529;
  background-color: #ffffff;
  top: 0;
  z-index: 1020;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  padding: 1rem;
}

.navbar>.container,
.navbar>.container-fluid {
  display: flex;
  flex-wrap: inherit;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  font-size: 1.75rem;
  text-decoration: none;
  white-space: nowrap;
  color: #0d6efd;
  font-weight: 700;
  padding-top: 0.3125rem;
  padding-bottom: 0.3125rem;
  margin-right: 1rem;
}

.icon-mortarboard-fill {
  margin-right: 0.5rem;
}

.nav-toggle {
  font-size: 1.25rem;
  line-height: 1;
  color: inherit;
  background-color: transparent;
  border: 1px solid rgba(128, 128, 128, 0.35);
  border-radius: 0.375rem;
  cursor: pointer;
  padding: 0.25rem 0.75rem;
}

.nav-toggle-icon {
  display: inline-block;
  width: 1.5em;
  height: 1.5em;
  vertical-align: middle;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%28128, 128, 128, 0.85%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100%;
}

.nav-collapse {
