.carousel {
  position: relative;
  border-radius: 2rem;
  overflow: hidden;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  border: 5px solid #ffffff;
}

.carousel-indicators {
  position: absolute;
  right: 0;
  bottom: 0.75rem;
  left: 0;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.carousel-indicators>* {
  width: 28px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background-color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
}

