  display: block;
  width: 100%;
}

.carousel-caption {
  position: absolute;
  right: 15%;
  bottom: 1.25rem;
  left: 15%;
  color: #ffffff;
  text-align: center;
  border-radius: 50rem;
  display: none;
  background-color: rgba(33, 37, 41, 0.5);
  padding: 1.25rem 1.5rem;
}

