  display: block;
  margin-bottom: 1rem;
}

.btn-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #212529;
  color: #ffffff;
  width: 100%;
