/* Custom Component Styles */
/* CSS Variables for TTC Theme */
:root {
  --ttc-primary: #004a99;
  --ttc-secondary: #ffcc00;
}

/* 2. Navigation with Mouse Hover Effect */
.hover-nav .nav-link {
  transition: all 0.3s ease;
  position: relative;
  padding: 1rem 1.2rem !important;
}

@media (min-width: 992px) {
  .hover-nav .nav-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 3px;
    bottom: 0;
    left: 0;
    background-color: var(--ttc-secondary);
    transition: width 0.3s ease;
  }

  .hover-nav .nav-link:hover::after {
    width: 100%;
  }

  .hover-nav .nav-link:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: var(--ttc-secondary) !important;
  }
}

.hero-img {
  height: 600px;
  object-fit: cover;
  filter: brightness(0.6);
}

.counter-box {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(5px);
  border-radius: 15px;
  padding: 2rem;
  transition: transform 0.3s;
}

.counter-box:hover {
  transform: translateY(-10px);
}

.principal-img {
  border: 8px solid #f8f9fa;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

/* Responsive Fixes */
@media (max-width: 768px) {
  .hero-img {
    height: 400px;
  }

}

