// Toggle collapsible sections & mobile menu
document.querySelectorAll('[data-toggle="collapse"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const target = targetSel ? document.querySelector(targetSel) : null;
    if (!target) return;
    const parentSel = target.getAttribute("data-parent");
    if (parentSel) {
      const parent = document.querySelector(parentSel);
      if (parent) {
        parent.querySelectorAll(".show").forEach((openEl) => {
          if (openEl !== target) openEl.classList.remove("show");
        });
        parent.querySelectorAll('[data-toggle="collapse"]').forEach((otherBtn) => {
          if (otherBtn !== btn) otherBtn.classList.add("collapsed");
        });
      }
    }
    const isOpen = target.classList.toggle("show");
    btn.classList.toggle("collapsed", !isOpen);
  });
});

// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

// Modal, Toast & Alert triggers
document.querySelectorAll('[data-toggle="modal"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const modal = targetSel ? document.querySelector(targetSel) : null;
    if (modal) {
      modal.classList.add("show");
      modal.removeAttribute("aria-hidden");
      modal.setAttribute("aria-modal", "true");
    }
  });
});

document.querySelectorAll("[data-dismiss]").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const kind = btn.getAttribute("data-dismiss");
    const target = btn.closest("." + kind + ", .alert-box, .modal, .toast");
    if (target) {
      target.classList.remove("show");
      if (target.classList.contains("modal") || kind === "modal") {
        target.setAttribute("aria-hidden", "true");
        target.removeAttribute("aria-modal");
      }
      if (kind === "alert") target.style.display = "none";
    }
  });
});

// 7. Current Date & Time / Year logic
function updateDateTime() {
  const now = new Date();
  const options = {
    weekday: 'short',
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  };
  document.getElementById('dateTimeDisplay').textContent = now.toLocaleDateString('en-US', options);
  document.getElementById('currentYear').textContent = now.getFullYear();
}
setInterval(updateDateTime, 1000);
updateDateTime();

// vi. JS Counters Animation
const counters = document.querySelectorAll('.counter');
const countSpeed = 200;

const startCounters = () => {
  counters.forEach(counter => {
    const updateCount = () => {
      const target = +counter.getAttribute('data-target');
      const count = +counter.innerText;
      const inc = target / countSpeed;
      if (count < target) {
        counter.innerText = Math.ceil(count + inc);
        setTimeout(updateCount, 1);
      } else {
        counter.innerText = target + "+";
      }
    };
    updateCount();
  });
};

// Trigger counters when section is in view
const statSection = document.querySelector('.counter').closest('section');
const observer = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting) startCounters();
}, {
  threshold: 0.5
});
observer.observe(statSection);

// 3. Login Submission Popup logic
document.getElementById('ttcLoginForm').addEventListener('submit', function(e) {
  e.preventDefault();
  // Hide Login Modal first
  {
    const _m = document.getElementById('loginModal');
    if (_m) {
      _m.classList.remove("show");
      _m.setAttribute("aria-hidden", "true");
      _m.removeAttribute("aria-modal");
    }
  }
  // Show Confirmation Modal
  const confirmModal = ({
    el: document.getElementById('confirmLoginModal'),
    show() {
      if (this.el) {
        this.el.classList.add("show");
        this.el.removeAttribute("aria-hidden");
        this.el.setAttribute("aria-modal", "true");
      }
    },
    hide() {
      if (this.el) {
        this.el.classList.remove("show");
        this.el.setAttribute("aria-hidden", "true");
        this.el.removeAttribute("aria-modal");
      }
    }
  });
  confirmModal.show();
});

