body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding: 1.5rem 1rem;
  margin-right: auto;
  margin-left: auto;
}

.navbar {
  margin-bottom: 1.5rem;
}

.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 0.5rem;
  border-radius: 1rem;
  background-color: #f8f9fa;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  border: 0;
  padding: 1rem;
  margin-bottom: 1rem;
}

.breadcrumb-item+.breadcrumb-item::before {
  content: "/";
  color: #6c757d;
  padding-right: 0.5rem;
}

.action-link {
  text-decoration: none;
  color: #0d6efd;
}

.hover-nav {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  color: #ffffff;
  border-radius: 1rem;
  background-color: #212529;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 1rem;
  margin-bottom: 3rem;
}

.hover-nav>.container,
.hover-nav>.container-fluid {
  display: flex;
  flex-wrap: inherit;
  align-items: center;
  justify-content: space-between;
}

.container-fluid {
  width: 100%;
  padding-right: 1rem;
  padding-left: 1rem;
}

.nav-brand {
  font-size: 1.25rem;
  text-decoration: none;
  white-space: nowrap;
  color: inherit;
  font-weight: 700;
  padding-top: 0.3125rem;
  padding-bottom: 0.3125rem;
  margin-right: 1rem;
}

.accent-text {
  color: #0d6efd;
}

.accent-text-light {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: #ffffff;
  font-size: 0.875rem;
  color: #6c757d;
  padding-right: 1rem;
  padding-left: 1rem;
}

.nav-toggle {
  font-size: 1.25rem;
  line-height: 1;
  color: inherit;
  background-color: transparent;
  border: 1px solid rgba(128, 128, 128, 0.35);
  border-radius: 0.375rem;
  cursor: pointer;
  padding: 0.25rem 0.75rem;
}

.nav-toggle-icon {
  display: inline-block;
  width: 1.5em;
  height: 1.5em;
  vertical-align: middle;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%28128, 128, 128, 0.85%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100%;
}

.nav-collapse {
  display: none;
  flex-basis: 100%;
  flex-grow: 1;
  align-items: center;
}

.nav-collapse.show {
  display: block;
}

.nav-menu {
  display: flex;
  flex-direction: column;
  list-style: none;
  width: 100%;
  justify-content: space-between;
  text-align: center;
  padding-left: 0;
  margin-top: 0;
  margin-bottom: 0;
}

.nav-item {
  list-style: none;
}

.nav-link {
  display: block;
  color: inherit;
  text-decoration: none;
  background: none;
  border: 0;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
  padding: 0.5rem 1rem;
}

.nav-link.nav-link-pill {
  border-radius: 50rem;
  font-weight: 700;
  padding-right: 0.85rem;
  padding-left: 0.85rem;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1rem;
  margin-right: -0.5rem;
  margin-left: -0.5rem;
}

.grid-row>* {
  width: 100%;
  max-width: 100%;
  padding-right: 0.5rem;
  padding-left: 0.5rem;
}

.grid-row-alt {
  display: flex;
  flex-wrap: wrap;
  row-gap: 3rem;
  align-items: center;
  margin-right: -1.5rem;
  margin-left: -1.5rem;
}

.grid-row-alt>* {
  width: 100%;
  max-width: 100%;
  padding-right: 1.5rem;
  padding-left: 1.5rem;
}

.col-half {
  width: 100%;
}

.col-half-alt {
  width: 100%;
  order: 2;
}

.col-half-3 {
  width: 100%;
  order: 1;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  word-wrap: break-word;
  background-color: #ffffff;
  background-clip: border-box;
  border-radius: 2rem;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  overflow: hidden;
  border: 0;
}

.card-header {
  background-color: #ffffff;
  border-bottom: 1px solid rgba(0, 0, 0, 0.125);
  border: 0;
  padding: 1.5rem 1rem 1rem;
}

.tab-nav {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 0.35rem;
  border-radius: 50rem;
  background-color: #f8f9fa;
  padding: 0.25rem;
  margin-bottom: 0;
}

.tab-nav>.nav-item,
.tab-nav>.nav-link {
  flex-basis: 0;
  flex-grow: 1;
  text-align: center;
}

.tab-content {
  flex: 1 1 auto;
  width: 100%;
  padding: 1.5rem;
}

.tab-pane {
  display: none;
}

.tab-pane.active,
.tab-pane.show {
  display: block;
}

.sub-title {
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.sub-title-alt {
  font-weight: 700;
}

.content-box {
  margin-bottom: 1rem;
}

.content-box-alt {
  margin-bottom: 1.5rem;
}

.form-label {
  display: inline-block;
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.input-group {
  position: relative;
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch;
  width: 100%;
}

.input-group>input,
.input-group>select,
.input-group>textarea {
  position: relative;
  flex: 1 1 auto;
  width: 1%;
  min-width: 0;
}

.input-addon {
  display: flex;
  align-items: center;
  font-size: 1rem;
  color: #212529;
  background-color: #ffffff;
  border-radius: 0.375rem;
  border-top-left-radius: 1rem;
  border-bottom-left-radius: 1rem;
  border: 2px solid #dee2e6;
  border-right: 0;
  padding: 0.5rem 0.75rem;
}

.icon-person {
  color: #6c757d;
}

.form-input {
  display: block;
  width: 100%;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  color: #212529;
  background-color: #f8f9fa;
  border-radius: 1rem;
  box-shadow: none;
  border: 0;
  padding: 0.5rem;
}

.form-input:focus {
  border-color: #86b7fe;
  outline: 0;
  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.form-input.form-input-alt {
  background-color: #ffffff;
  border-radius: 0.375rem;
  border-top-right-radius: 1rem;
  border-bottom-right-radius: 1rem;
  border: 2px solid #dee2e6;
  border-left: 0;
}

.icon-shield-lock {
  color: #6c757d;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  padding: 0.5rem 1rem;
}

.btn-primary:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.btn-primary-alt {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #0d6efd;
  border-radius: 1rem;
  transition: all 0.2s ease;
  background-color: #0d6efd;
  color: #ffffff;
  width: 100%;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 1rem;
  margin-bottom: 1.5rem;
}

.btn-primary-alt:hover {
  background-color: #0b5ed7;
  border-color: #0b5ed7;
  color: #ffffff;
}

.section-header {
  text-align: center;
  position: relative;
  margin-bottom: 1.5rem;
}

.btn-outline-secondary {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #6c757d;
  border-radius: 50rem;
  transition: all 0.2s ease;
  background-color: transparent;
  color: #6c757d;
  width: 100%;
  padding: 0.5rem 1rem;
}

.btn-outline-secondary:hover {
  background-color: #6c757d;
  color: #ffffff;
}

.icon-google {
  color: #dc3545;
  margin-right: 0.5rem;
}

.icon-facebook {
  color: #0d6efd;
  margin-right: 0.5rem;
}

.btn-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  border: 1px solid #212529;
  border-radius: 1rem;
  transition: all 0.2s ease;
  background-color: #212529;
  color: #ffffff;
  width: 100%;
  padding: 1rem;
}

.btn-dark:hover {
  background-color: #424649;
  border-color: #424649;
  color: #ffffff;
}

.carousel {
  position: relative;
}

.carousel-inner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.carousel-item {
  display: none;
  position: relative;
  width: 100%;
}

.carousel-item.active {
  display: block;
}

.surface-box {
  border-radius: 2rem;
  background-color: #0d6efd;
  background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.15), rgba(255, 255, 255, 0));
  color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  text-align: center;
  padding: 3rem;
}

.surface-box-center {
  border-radius: 2rem;
  background-color: #dc3545;
  background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.15), rgba(255, 255, 255, 0));
  color: #ffffff;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  text-align: center;
  padding: 3rem;
}

.icon-gift-fill {
  font-size: clamp(2.75rem, 5vw, 5rem);
  font-weight: 300;
  line-height: 1.2;
  margin-bottom: 1.5rem;
}

.section-title {
  font-weight: 700;
}

.text-desc {
  margin-bottom: 1.5rem;
}

.badge {
  display: inline-block;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1;
  color: #0d6efd;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #ffffff;
  padding: 0.5rem 1.5rem;
}

.badge-light {
  display: inline-block;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1;
  color: #dc3545;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 50rem;
  background-color: #ffffff;
  padding: 0.5rem 1.5rem;
}

.icon-truck {
  font-size: clamp(2.75rem, 5vw, 5rem);
  font-weight: 300;
  line-height: 1.2;
  margin-bottom: 1.5rem;
}

.carousel-indicators {
  position: relative;
  right: 0;
  bottom: 0.75rem;
  left: 0;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
  margin: 1.5rem 0 0;
}

.carousel-indicators>* {
  width: 28px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background-color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
}

.carousel-indicators>.active {
  background-color: #ffffff;
}

.action-btn {
  border-radius: 50%;
}

.modal {
  position: fixed;
  inset: 0;
  z-index: 1055;
  display: none;
  overflow-x: hidden;
  overflow-y: auto;
  background-color: rgba(0, 0, 0, 0.5);
}

.modal.show {
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-dialog {
  position: relative;
  width: 100%;
  max-width: 500px;
  margin: 1.75rem auto;
}

.modal-content {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  background-color: #ffffff;
  border: 0;
  border-radius: 2rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.modal-body {
  position: relative;
  flex: 1 1 auto;
  text-align: center;
  padding: 3rem;
}

.icon-patch-check-fill {
  color: #198754;
}

.muted-text {
  color: #6c757d;
}

.grid-stack {
  display: grid;
  margin-top: 1.5rem;
}

@media (min-width: 576px) {
  .col-half {
    flex: 0 0 auto;
    width: 50%;
  }
}

@media (min-width: 768px) {
  .tab-content {
    padding: 3rem;
  }
}

@media (min-width: 992px) {
  .hover-nav {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .nav-toggle {
    display: none;
  }

  .nav-collapse {
    display: flex !important;
    flex-basis: auto;
  }

  .nav-menu {
    flex-direction: row;
    align-items: center;
  }

  .col-half-alt {
    flex: 0 0 auto;
    width: 50%;
    order: 1;
  }

  .col-half-3 {
    flex: 0 0 auto;
    width: 50%;
    order: 2;
  }
}

/* Custom Component Styles */
/* Full container wide navigation hover effect */
.hover-nav .nav-link {
  transition: all 0.3s ease;
  position: relative;
}

.hover-nav .nav-link:after {
  content: '';
  position: absolute;
  width: 0;
  height: 2px;
  bottom: 0;
  left: 0;
  background-color: #0d6efd;
  transition: width 0.3s ease;
}

.hover-nav .nav-link:hover:after {
  width: 100%;
}

.hover-nav .nav-link:hover {
  color: #0d6efd !important;
  transform: translateY(-2px);
}

/* Form Customization */
.tab-nav .nav-link.active {
  background-color: #fff !important;
  color: #0d6efd !important;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.tab-nav .nav-link {
  color: #6c757d;
}

.carousel-item {
  min-height: 400px;
}

@media (max-width: 991px) {
  .nav-menu {
    padding-top: 20px;
  }

  .hover-nav .nav-link:after {
    display: none;
  }
}

/* Inline SVG Icons */

.icon-person::before,
.icon-shield-lock::before,
.icon-google::before,
.icon-facebook::before,
.icon-gift-fill::before,
.icon-truck::before,
.icon-patch-check-fill::before {
  content: "";
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: -0.125em;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
}

