// Toggle collapsible sections & mobile menu
document.querySelectorAll('[data-toggle="collapse"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const target = targetSel ? document.querySelector(targetSel) : null;
    if (!target) return;
    const parentSel = target.getAttribute("data-parent");
    if (parentSel) {
      const parent = document.querySelector(parentSel);
      if (parent) {
        parent.querySelectorAll(".show").forEach((openEl) => {
          if (openEl !== target) openEl.classList.remove("show");
        });
        parent.querySelectorAll('[data-toggle="collapse"]').forEach((otherBtn) => {
          if (otherBtn !== btn) otherBtn.classList.add("collapsed");
        });
      }
    }
    const isOpen = target.classList.toggle("show");
    btn.classList.toggle("collapsed", !isOpen);
  });
});

// Switch tabs / pills
document.querySelectorAll('[data-toggle="pill"], [data-toggle="tab"], [data-toggle="list"]').forEach((tabBtn) => {
  tabBtn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = tabBtn.getAttribute("data-target") || tabBtn.getAttribute("href");
    const target = targetSel ? document.querySelector(targetSel) : null;
    const nav = tabBtn.closest(".tab-nav, .nav-menu, .list-group, ul, nav") || tabBtn.parentElement;
    if (nav) {
      nav.querySelectorAll(".active").forEach((el) => el.classList.remove("active"));
    }
    tabBtn.classList.add("active");
    if (target && target.parentElement) {
      Array.from(target.parentElement.children).forEach((pane) => {
        pane.classList.remove("show", "active");
      });
      target.classList.add("show", "active");
    }
  });
});

// Carousel slider controls
document.querySelectorAll(".carousel").forEach((carousel) => {
  const items = Array.from(carousel.querySelectorAll(".carousel-item"));
  if (items.length <= 1) return;
  const indicators = Array.from(carousel.querySelectorAll("[data-slide-to]"));

  const showSlide = (nextIdx) => {
    const idx = (nextIdx + items.length) % items.length;
    items.forEach((item, i) => item.classList.toggle("active", i === idx));
    indicators.forEach((ind, i) => ind.classList.toggle("active", i === idx));
  };

  const getActiveIndex = () => {
    const i = items.findIndex((el) => el.classList.contains("active"));
    return i >= 0 ? i : 0;
  };

  carousel.querySelectorAll('[data-slide="prev"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() - 1);
    });
  });

  carousel.querySelectorAll('[data-slide="next"]').forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      showSlide(getActiveIndex() + 1);
    });
  });

  indicators.forEach((ind) => {
    ind.addEventListener("click", (e) => {
      e.preventDefault();
      const to = Number(ind.getAttribute("data-slide-to") || 0);
      showSlide(to);
    });
  });

  if (carousel.getAttribute("data-ride") === "carousel") {
    const interval = parseInt(carousel.getAttribute("data-interval"), 10) || 5000;
    setInterval(() => {
      showSlide(getActiveIndex() + 1);
    }, interval);
  }
});

// Modal, Toast & Alert triggers
document.querySelectorAll('[data-toggle="modal"]').forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const targetSel = btn.getAttribute("data-target") || btn.getAttribute("href");
    const modal = targetSel ? document.querySelector(targetSel) : null;
    if (modal) {
      modal.classList.add("show");
      modal.removeAttribute("aria-hidden");
      modal.setAttribute("aria-modal", "true");
    }
  });
});

document.querySelectorAll("[data-dismiss]").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    const kind = btn.getAttribute("data-dismiss");
    const target = btn.closest("." + kind + ", .alert-box, .modal, .toast");
    if (target) {
      target.classList.remove("show");
      if (target.classList.contains("modal") || kind === "modal") {
        target.setAttribute("aria-hidden", "true");
        target.removeAttribute("aria-modal");
      }
      if (kind === "alert") target.style.display = "none";
    }
  });
});

// Handle form submission and show confirmation modal
document.getElementById('loginForm').addEventListener('submit', function(event) {
  event.preventDefault();
  const confirmationModal = ({
    el: document.getElementById('submitModal'),
    show() {
      if (this.el) {
        this.el.classList.add("show");
        this.el.removeAttribute("aria-hidden");
        this.el.setAttribute("aria-modal", "true");
      }
    },
    hide() {
      if (this.el) {
        this.el.classList.remove("show");
        this.el.setAttribute("aria-hidden", "true");
        this.el.removeAttribute("aria-modal");
      }
    }
  });
  confirmationModal.show();
});

css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  color: #212529;
  background-color: #ffffff;
}

a {
  color: inherit;
}

img,
svg {
  vertical-align: middle;
}

button,
input,
select,
textarea {
  font: inherit;
}

.section-block {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-light {
  background-color: #f8f9fa;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-3 {
  background-color: #f8f9fa;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-block-primary {
  background-color: #0d6efd;
  color: #ffffff;
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.container {
  width: 100%;
  max-width: 1200px;
  padding-right: 1rem;
  padding-left: 1rem;
  margin-right: auto;
  margin-left: auto;
}

.container.container-alt {
  margin-top: 1.5rem;
}

.container.container-3 {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.container.container-4 {
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

.container.container-center {
  text-align: center;
  align-items: center;
}

.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  gap: 0.5rem;
  padding: 0;
  margin-bottom: 1rem;
}

.breadcrumb-item+.breadcrumb-item::before {
  content: "/";
  color: #6c757d;
  padding-right: 0.5rem;
}

.action-link {
  text-decoration: none;
}

.action-link-sm {
  color: #ffffff;
  text-decoration: none;
  font-size: 0.875rem;
}

.action-link-3 {
  color: #ffffff;
  text-decoration: none;
  font-size: 0.875rem;
  margin-right: 1.5rem;
}

.hero-title {
  font-size: clamp(2rem, 3.5vw, 3.5rem);
  line-height: 1.2;
  font-weight: 700;
}

.grid-row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 1.5rem;
  margin-right: -0.75rem;
  margin-left: -0.75rem;
}

.grid-row>* {
